'use client';
import {useActionState} from 'react';import {vendorLogin} from '@/app/vendor/actions';import {PasswordField} from '@/components/password-field';
export function VendorLoginForm({initialError}:{initialError?:string}){const[state,action,pending]=useActionState(vendorLogin,{error:initialError});return <form action={action}><label className="field"><span>Email</span><input name="email" type="email" autoComplete="email" required/></label><PasswordField name="password"/>{state.error?<div className="form-feedback error" role="alert">{state.error}</div>:null}<button className="btn btn-dark" disabled={pending}>{pending?'Connexion…':'Se connecter'}</button></form>}
